import 'weapon_data.dart';
class WeaponRuntime { final WeaponData data; int ammo; double heat = 0; double cooldownRemaining = 0; WeaponRuntime(this.data) : ammo = data.magazine; bool get overheated => data.overheats && heat >= 100; bool get canFire => cooldownRemaining <= 0 && !overheated && (data.magazine == 0 || ammo > 0); bool fire() { if (!canFire) return false; cooldownRemaining = data.cooldown; if (data.magazine > 0) ammo--; if (data.overheats) heat = (heat + 22).clamp(0, 120).toDouble(); return true; } void update(double dt) { cooldownRemaining = (cooldownRemaining - dt).clamp(0, 999).toDouble(); heat = (heat - 12 * dt).clamp(0, 100).toDouble(); } void reload() { ammo = data.magazine; } Map<String, dynamic> toJson() => {'id': data.id.name, 'ammo': ammo, 'heat': heat}; }
class WeaponSystem { WeaponId equipped = WeaponId.bolter; final Map<WeaponId, WeaponRuntime> weapons = {for (final id in WeaponId.values) id: WeaponRuntime(WeaponData.all[id]!)}; WeaponRuntime get current => weapons[equipped]!; bool fire() => current.fire(); void update(double dt) { for (final weapon in weapons.values) { weapon.update(dt); } } Map<String, dynamic> toJson() => {'equipped': equipped.name, 'weapons': weapons.map((k,v) => MapEntry(k.name, v.toJson()))}; void loadJson(dynamic json) { if (json is! Map) return; equipped = WeaponId.values.firstWhere((e) => e.name == json['equipped'], orElse: () => WeaponId.bolter); final raw = json['weapons']; if (raw is Map) { for (final id in WeaponId.values) { final entry = raw[id.name]; if (entry is Map) { final w = weapons[id]!; w.ammo = (entry['ammo'] as num?)?.toInt() ?? w.data.magazine; w.heat = (entry['heat'] as num?)?.toDouble() ?? 0; } } } } }
